pub unsafe fn lodepng_chunk_append(
    mut out: *mut *mut c_uchar,
    mut outsize: *mut size_t,
    mut chunk: *const c_uchar,
) -> c_uint {
    let mut i: c_uint = 0;
    let mut total_chunk_length: size_t = 0;
    let mut new_length: size_t = 0;
    let mut chunk_start: *mut c_uchar =
        ::core::ptr::null_mut::<c_uchar>();
    let mut new_buffer: *mut c_uchar = ::core::ptr::null_mut::<c_uchar>();
    if lodepng_chunk_type_name_valid(chunk) == 0 {
        return 121 as c_uint;
    }
    if lodepng_chunk_reserved(chunk) != 0 {
        return 122 as c_uint;
    }
    if lodepng_addofl(
        lodepng_chunk_length(chunk) as size_t,
        12 as size_t,
        &raw mut total_chunk_length,
    ) != 0
    {
        return 77 as c_uint;
    }
    if lodepng_addofl(*outsize, total_chunk_length, &raw mut new_length) != 0 {
        return 77 as c_uint;
    }
    new_buffer =
        lodepng_realloc(*out as *mut c_void, new_length) as *mut c_uchar;
    if new_buffer.is_null() {
        return 83 as c_uint;
    }
    *out = new_buffer;
    *outsize = new_length;
    chunk_start = (*out).offset(new_length.wrapping_sub(total_chunk_length) as isize)
        as *mut c_uchar;
    i = 0 as c_uint;
    while i as size_t != total_chunk_length {
        *chunk_start.offset(i as isize) = *chunk.offset(i as isize);
        i = i.wrapping_add(1);
    }
    return 0 as c_uint;
}
